src='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = set()
            while q:
                y, x = q.popleft()
                comp.add((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            r0=min(y for y,x in comp); r1=max(y for y,x in comp)
            c0=min(x for y,x in comp); c1=max(x for y,x in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            border={(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                    if y in (r0,r1) or x in (c0,c1)}
            if border <= comp:
                fill = 2 if (r1-r0-1) == (c1-c0-1) else 7
                for y in range(r0+1,r1):
                    for x in range(c0+1,c1):
                        out[y][x]=fill
    return out
'''
